(1, 'a1-time-frequency', '62ba683ed9e7e84cc7acf829389e9637f6d84eb878eb3a1bbdd4bee9e5d310ce', 'after', 'preposition', 'A1', 'Subsequently to; following in time; later than.', 'sau', '/ˈæf.tə(ɹ)/', 'We went home after lunch.', 'Chúng tôi về nhà sau bữa trưa.', NULL, NULL, NULL, '{"cefrj":{"source":"CEFR-J Wordlist Version 1.6","compiler":"Yukio Tono, Tokyo University of Foreign Studies","version":"1.6","worksheet":"A1","row":14,"url":"https://cefr-j.org/download_eng"},"dictionary":{"api":"Free Dictionary API","url":"https://api.dictionaryapi.dev/api/v2/entries/en/after","senseLocator":"Task 01 verified source record","underlyingPage":"https://en.wiktionary.org/wiki/after","license":"CC BY-SA 3.0 or later / GFDL","licenseUrl":"https://en.wiktionary.org/wiki/Wiktionary:Copyrights","posMatch":true,"selectionMethod":"English sense matched to the cited Vietnamese gloss."},"vietnamese":{"url":"https://vi.wiktionary.org/wiki/after","source":"Vietnamese Wiktionary via Kaikki 2026-10-02","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","sourceGloss":"Sau, sau khi.","senseLocator":"prep:1","reviewStatus":"VERIFIED","adaptation":"Selected and normalized part of the source gloss."},"examples":{"english":"English Learning App (original example)","englishUrl":null,"vietnamese":"English Learning App (example translation)"}}'),
(2, 'a1-time-frequency', 'a129121db71581a5b8d8310000ff93dc8813142056c6fd05be54e38b501499d1', 'afternoon', 'noun', 'A1', 'The part of the day from noon or lunchtime until sunset, evening, or suppertime or 6pm.', 'buổi chiều', '/af.təɾˈnʉːn/', 'I will call you this afternoon.', 'Tôi sẽ gọi cho bạn chiều nay.', NULL, NULL, NULL, '{"cefrj":{"source":"CEFR-J Wordlist Version 1.6","compiler":"Yukio Tono, Tokyo University of Foreign Studies","version":"1.6","worksheet":"A1","row":15,"url":"https://cefr-j.org/download_eng"},"dictionary":{"api":"Free Dictionary API","url":"https://api.dictionaryapi.dev/api/v2/entries/en/afternoon","senseLocator":"Task 01 verified source record","underlyingPage":"https://en.wiktionary.org/wiki/afternoon","license":"CC BY-SA 3.0 or later / GFDL","licenseUrl":"https://en.wiktionary.org/wiki/Wiktionary:Copyrights","posMatch":true,"selectionMethod":"English sense matched to the cited Vietnamese gloss."},"vietnamese":{"url":"https://vi.wiktionary.org/wiki/afternoon","source":"Vietnamese Wiktionary via Kaikki 2026-10-02","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","sourceGloss":"Buổi chiều.","senseLocator":"noun:1","reviewStatus":"VERIFIED","adaptation":"Selected and normalized part of the source gloss."},"examples":{"english":"English Learning App (original example)","englishUrl":null,"vietnamese":"English Learning App (example translation)"}}'),
(3, 'a1-time-frequency', '57700d1585e56204cb47abea9361938dc941e5f467366e055e4d114651b03126', 'again', 'adverb', 'A1', 'Another time; once more.', 'lần nữa', '/əˈɡeɪn/', 'Great, thanks again!', 'Tuyệt quá, cảm ơn bạn lần nữa nhé!', NULL, NULL, NULL, '{"cefrj":{"source":"CEFR-J Wordlist Version 1.6","compiler":"Yukio Tono, Tokyo University of Foreign Studies","version":"1.6","worksheet":"A1","row":16,"url":"https://cefr-j.org/download_eng"},"dictionary":{"api":"Free Dictionary API","url":"https://api.dictionaryapi.dev/api/v2/entries/en/again","senseLocator":"Task 01 verified source record","underlyingPage":"https://en.wiktionary.org/wiki/again","license":"CC BY-SA 3.0 or later / GFDL","licenseUrl":"https://en.wiktionary.org/wiki/Wiktionary:Copyrights","posMatch":true,"selectionMethod":"English sense matched to the cited Vietnamese gloss."},"vietnamese":{"url":"https://vi.wiktionary.org/wiki/again","source":"Vietnamese Wiktionary via Kaikki 2026-10-02","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","sourceGloss":"Lại, lần nữa, nữa.","senseLocator":"adv:1","reviewStatus":"VERIFIED","adaptation":"Selected and normalized part of the source gloss."},"examples":{"english":"Free Dictionary API","englishUrl":"https://api.dictionaryapi.dev/api/v2/entries/en/again","vietnamese":"English Learning App (example translation)"}}'),
