(5, 'a1-time-frequency', '1c7f8e68c1f83d0aaa65945672b4e372e4c62fef49556467a7e60a465ffd1da5', 'already', 'adverb', 'A1', 'Prior to some specified time, either past, present, or future; by this time; previously.', 'đã', '/ɑlˈɹɛdi/', 'I have already eaten lunch.', 'Tôi đã ăn trưa rồi.', NULL, NULL, NULL, '{"cefrj":{"source":"CEFR-J Wordlist Version 1.6","compiler":"Yukio Tono, Tokyo University of Foreign Studies","version":"1.6","worksheet":"A1","row":30,"url":"https://cefr-j.org/download_eng"},"dictionary":{"api":"Free Dictionary API","url":"https://api.dictionaryapi.dev/api/v2/entries/en/already","senseLocator":"Task 01 verified source record","underlyingPage":"https://en.wiktionary.org/wiki/already","license":"CC BY-SA 3.0 or later / GFDL","licenseUrl":"https://en.wiktionary.org/wiki/Wiktionary:Copyrights","posMatch":true,"selectionMethod":"English sense matched to the cited Vietnamese gloss."},"vietnamese":{"url":"https://vi.wiktionary.org/wiki/already","source":"Vietnamese Wiktionary via Kaikki 2026-10-02","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","sourceGloss":"Đã, rồi; đã... rồi.","senseLocator":"adv:1","reviewStatus":"VERIFIED","adaptation":"Selected and normalized part of the source gloss."},"examples":{"english":"English Learning App (original example)","englishUrl":null,"vietnamese":"English Learning App (example translation)"}}'),
