(7, 'a1-time-frequency', 'c4dfaca0297671bac68f6dca1f2f3e6bc38316e135443802c8f0145f203a19d0', 'autumn', 'noun', 'A1', 'Traditionally the third of the four seasons, when deciduous trees lose their leaves; typically regarded as being from September 24 to December 22 in parts of the Northern Hemisphere, and the months of March, April and May in the Southern Hemisphere.', 'mùa thu', '/ˈɔːtəm/', 'The leaves turn yellow in autumn.', 'Lá chuyển sang màu vàng vào mùa thu.', NULL, NULL, NULL, '{"cefrj":{"source":"CEFR-J Wordlist Version 1.6","compiler":"Yukio Tono, Tokyo University of Foreign Studies","version":"1.6","worksheet":"A1","row":60,"url":"https://cefr-j.org/download_eng"},"dictionary":{"api":"Free Dictionary API","url":"https://api.dictionaryapi.dev/api/v2/entries/en/autumn","senseLocator":"Task 01 verified source record","underlyingPage":"https://en.wiktionary.org/wiki/autumn","license":"CC BY-SA 3.0 or later / GFDL","licenseUrl":"https://en.wiktionary.org/wiki/Wiktionary:Copyrights","posMatch":true,"selectionMethod":"English sense matched to the cited Vietnamese gloss."},"vietnamese":{"url":"https://vi.wiktionary.org/wiki/autumn","source":"Vietnamese Wiktionary via Kaikki 2026-10-02","attribution":"Wiktionary contributors","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","sourceGloss":"Mùa thu.","senseLocator":"noun:1","reviewStatus":"VERIFIED","adaptation":"Selected and normalized part of the source gloss."},"examples":{"english":"English Learning App (original example)","englishUrl":null,"vietnamese":"English Learning App (example translation)"}}'),
